E={
'h-guerras-001':(['A Macedônia entra depois, aproveitando a Grécia enfraquecida.','Só as Médicas foram contra os persas; o Peloponeso foi grego contra grego.','Esparta não perdeu as Médicas: gregos venceram juntos.'],['Médicas → Atenas forte → rivalidade com Esparta → Peloponeso.'],'Atenas venceu as Médicas e perdeu o Peloponeso.'),
'h-guerras-002':(['As Médicas vieram ANTES do Peloponeso.','Os persas já tinham sido derrotados nas Médicas.','Quem se fortaleceu foi Atenas nas Médicas; o Peloponeso enfraqueceu as pólis.'],['Peloponeso → pólis enfraquecidas → Macedônia domina a Grécia.'],'Consequência das Médicas = Atenas forte; do Peloponeso = Grécia fraca.'),
'h-guerras-003':(['Roma não participou.','Gregos × persas são as Guerras Médicas.','Os macedônios só dominaram a Grécia depois.'],['Peloponeso: Atenas × Esparta.'],'Peloponeso é o nome da península onde fica Esparta.'),
'h-guerras-004':(['É antes de Cristo, e a data inicial vem primeiro.','331 a.C. é a época de Alexandre.','499–449 a.C. são as Guerras Médicas.'],['Médicas: 499–449 a.C.','Peloponeso: 431–404 a.C.'],'Em a.C., a guerra começa no número maior (431) e termina no menor (404).'),
'h-guerras-005':(['Grécia × Macedônia não é o nome dessa guerra.','Atenas × Esparta é o Peloponeso.','Atenas foi a protagonista das Médicas.'],['Médicas: gregos unidos × persas.'],'"Medos" eram povos do Império Persa; daí "Médicas".'),
'h-guerras-006':(['Esparta vencendo Atenas é o Peloponeso.','Macedônia dominou depois do Peloponeso.','Os persas perderam.'],['Médicas: vitória grega e Atenas fortalecida (Liga de Delos).'],'Atenas fortalecida depois das Médicas é justamente o que gerou a rivalidade com Esparta.'),
'h-guerras-007':(['Escola de filosofia não é pólis.','Pólis é grega, não persa.','Templo é construção religiosa.'],['Pólis: cidade-Estado independente, com governo e leis próprios.'],'Por serem independentes, as pólis podiam até guerrear entre si.'),
'h-guerras-008':(['Os persas não lutaram essa guerra como protagonistas.','Esparta venceu.','A Macedônia entrou depois.'],['Peloponeso: Esparta vence; Atenas perde a liderança.'],'Atenas venceu as Médicas e perdeu o Peloponeso. Inverter é o erro mais comum.'),
'h-guerras-009':(['A Macedônia só chega depois do Peloponeso.','As Médicas vieram primeiro.','A dominação macedônica é o fim da sequência.'],['Médicas (499–449) → Peloponeso (431–404) → Macedônia.'],'Em a.C., número maior = mais antigo.'),
'h-guerras-010':(['É antes de Cristo, e o início é o número maior.','431–404 a.C. é o Peloponeso.','Datas invertidas e da outra guerra.'],['Médicas: 499–449 a.C. (primeiro).'],'Médicas vieram primeiro, por isso os números são maiores.'),
'h-guerras-011':(['Conta errada: 449 − 431 = 18.','45 viria de confundir as datas.','880 seria somar as duas, mas as datas estão do mesmo lado de Cristo.'],['Duas datas a.C.: subtraia. Uma a.C. e outra d.C.: some.'],'Somar só quando uma data é a.C. e a outra d.C.'),
'h-roma-001':(['Proteger contra invasões era função de muralhas.','Grãos ficavam em celeiros.','Observar estrelas não era função de aqueduto.'],['Aqueduto: leva água às cidades.'],'Os arcos famosos eram só a parte que atravessava vales; boa parte era subterrânea.'),
'h-roma-002':(['Grego influenciou palavras, mas não originou o português.','Egípcio não tem relação com o português.','Árabe deixou palavras (açúcar, almofada), mas não é a origem.'],['Latim → português, espanhol, italiano, francês (línguas neolatinas).'],'Muitas palavras científicas vêm do grego, mas a língua portuguesa vem do latim.'),
'h-roma-003':(['Partenon é templo grego, em Atenas.','Aqueduto leva água.','Zigurate é templo mesopotâmico.'],['Coliseu: anfiteatro romano, lutas de gladiadores.'],'Partenon (Grécia) × Coliseu (Roma): cai muito junto.'),
'h-roma-004':(['Faraó é do Egito.','Patrícios eram a elite dona de terras.','Senadores eram, em geral, patrícios.'],['Plebeus: maioria livre (comerciantes, artesãos, camponeses).'],'Plebeu não era escravo: era livre, mas sem direitos políticos no início.'),
'h-roma-005':(['Zeus e Hera são deuses gregos.','Hamurabi e Nabucodonosor são reis da Babilônia.','Péricles e Sócrates são de Atenas.'],['Lenda: Rômulo e Remo, amamentados por uma loba.'],'É lenda, não fato: a arqueologia mostra migrações de vários povos.'),
'h-roma-006':(['Plebeus eram a maioria trabalhadora.','Clientes eram dependentes dos patrícios.','Escravizados não eram donos de nada.'],['Patrícios: elite dona de terras e do poder.'],'Patrício lembra "pai/pátria": as famílias tradicionais.'),
'h-roma-007':(['1453 é a queda de Constantinopla (Império do Oriente).','753 a.C. é a fundação lendária de Roma.','1500 é a chegada dos portugueses ao Brasil.'],['476: queda do Império Romano do Ocidente → início da Idade Média.'],'O Império do Oriente durou até 1453; não confunda as duas quedas.'),
'h-roma-008':(['Budismo é da Ásia.','Islamismo surgiu no século VII, depois.','Judaísmo existia, mas não virou religião oficial de Roma.'],['Cristianismo: perseguido, depois liberado (313) e oficial (380).'],'Roma começou politeísta e terminou cristã.'),
'h-roma-009':(['Júlio César foi ditador, nunca imperador.','Nero governou depois.','Constantino veio séculos depois.'],['Otávio Augusto: primeiro imperador, 27 a.C.'],'"César" virou título, mas Júlio César não foi imperador.'),
'h-roma-010':(['Não tem a ver com construir padarias.','Era o contrário: dar pão, não cobrar.','Era o contrário: oferecer espetáculos.'],['Pão e circo: comida e diversão para evitar revoltas.'],'Hoje a expressão critica governos que distraem o povo.'),
'h-roma-011':(['A Monarquia veio primeiro.','O Império foi a última fase.','A República vem antes do Império.'],['Monarquia (753 a.C.) → República (509 a.C.) → Império (27 a.C.).'],'"M-R-I": Monarquia, República, Império.'),
'h-rep1-001':(['Dependentes e agregados eram os clientes.','A grande maioria trabalhadora eram os plebeus.','Obtidos por guerra ou dívidas eram os escravizados.','Soldados estrangeiros não eram uma camada social.'],['Patrícios: terras e poder.','Plebeus: maioria. Clientes: dependentes. Escravos: guerra ou dívida.'],'Na prova, cada camada tem uma frase típica; associe a frase à camada.'),
'h-rep1-002':(['Governo de um só é monarquia.','Governo de generais lembra os triunviratos.','Lei escrita é a Lei das 12 Tábuas.','"Nosso mar" é Mare Nostrum.'],['Res Publica = coisa pública, coisa do povo.'],'Na prática, a "coisa do povo" era controlada pelos patrícios.'),
'h-rep1-003':(['Otávio é do fim da República, séculos depois.','Rômulo e Remo são a lenda, não a História.','Os persas não invadiram a Itália.','O Senado só existe depois que Roma já existe.'],['Mito: Rômulo e Remo.','História: migrações de etruscos, latinos e gregos.'],'A pergunta pede "segundo a História": descarte a lenda.'),
'h-rep1-004':(['Democracia é legado de Atenas.','Arte rupestre é da Pré-história.','Pirâmides são do Egito.','Cuneiforme é da Mesopotâmia.'],['Direito Romano: base das leis do Ocidente, inclusive do Brasil.'],'Grécia = democracia e filosofia; Roma = Direito.'),
'h-rep1-005':(['Reis etruscos governaram na Monarquia.','Dependentes dos patrícios eram os clientes.','Donos das terras eram os patrícios.','"Instrumentos de trabalho" eram os escravizados.'],['Plebeus: maioria que trabalhava e lutava, sem direitos políticos no início.'],'Plebeu era livre; escravizado não.'),
'h-rep1-006':(['Roma já não tinha rei.','A primeira lei escrita foi a das 12 Tábuas.','Tribuno não era tribunal.','Tribuno não comandava exército.'],['Tribuno da Plebe: representante com poder de veto.'],'Tribuno ≠ tribunal. Tribuno é pessoa; vetava leis contra a plebe.'),
'h-rep1-007':(['Excesso de terras e dinheiro era dos patrícios.','Esses problemas não são os estudados.','Religião, festas e comércio não eram proibidos.','Guerras Púnicas e triunviratos vêm depois.'],['Panela de pressão: alistamento obrigatório, exploração e escravidão por dívidas.'],'Escravidão por dívida atingia plebeus livres: daí a revolta.'),
'h-rep1-008':(['Escravo não escolhia e não recebia salário.','Nascer em Roma não tornava ninguém escravo.','O Senado não votava quem virava escravo.','Filho de patrício era da elite.'],['Escravidão: prisioneiros de guerra ou dívidas.'],'Mais guerras vencidas = mais escravos. Isso alimenta a crise da República.'),
'h-rep1-009':(['A Monarquia veio primeiro.','O Império vem depois da República.','Ordem invertida.','A Monarquia é a primeira.'],['Monarquia → República → Império.'],'Em quase toda prova sobre Roma, essa ordem aparece.'),
'h-rep1-010':(['Tribunos representavam a plebe.','Prisioneiros de guerra viravam escravos.','Cliente romano não era comprador de loja.','Donos de terras eram os patrícios.'],['Clientes: dependentes e agregados dos patrícios.'],'"Cliente" tinha outro sentido em Roma: dependente, não comprador.'),
'h-rep1-011':(['As 12 Tábuas não acabaram com a escravidão.','Imperador só surge com Otávio.','Escravos nunca votaram.','Reforma agrária foi proposta depois, pelos Graco.'],['12 Tábuas: primeiras leis escritas, regras conhecidas por todos.'],'Lei escrita protege porque ninguém pode inventar a regra na hora.'),
'h-rep1-012':(['Escravos não governavam.','A Monarquia já tinha acabado.','Nem todos votavam igualmente.','Era o contrário: só patrícios no Senado.'],['República: em teoria de todos; na prática, dos patrícios.'],'"Coisa pública" privada = o nome dizia uma coisa, a realidade era outra.'),
'h-rep1-013':(['A plebe não tinha dinheiro para comprar cargos.','Cartago era inimiga de Roma.','A plebe não assassinou patrícios.','Fugir não dava direitos.'],['Greve da plebe: sem soldados e sem trabalhadores, Roma parava.'],'A força da plebe era ser a maioria que trabalhava e lutava.'),
'h-rep1-014':(['O rei não renunciou.','A greve da plebe é já na República.','Otávio é do fim da República.','Cartago não invadiu Roma nessa época.'],['Fim da Monarquia: golpe dos patrícios contra os reis etruscos (509 a.C.).'],'Quem derrubou o rei foi a elite, não o povo.'),
'h-rep1-015':(['Tribunos surgem na República.','A plebe não tinha poder político no início.','Escravos não governavam.','Triunviratos são do fim da República.'],['Senado: conselho de patrícios ao lado do rei.'],'O Senado existiu na Monarquia, na República e no Império.'),
'h-rep1-016':(['César e Pompeu são do fim da República.','Otávio e Marco Antônio também.','Os Graco foram tribunos da plebe.','Os reis etruscos vieram depois da fundação.'],['Lenda: Rômulo e Remo, salvos por uma loba.'],'A Eneida também conta que Eneias, de Troia, é antepassado dos gêmeos.'),
'h-rep1-017':(['O exército continuou e cresceu.','Latifúndios prejudicaram a plebe.','A monarquia não voltou.','O Senado continuou dominado por patrícios.'],['Conquistas: Tribuno da Plebe, 12 Tábuas, fim da escravidão por dívidas.'],'Conquistar direitos não é o mesmo que controlar o governo.'),
'h-rep1-018':(['Mare Nostrum é o Mediterrâneo dominado por Roma.','Etrúria é a região dos etruscos, no centro-norte.','Res Publica é a República.','Cartago fica no norte da África.'],['Magna Grécia: colônias gregas no sul da Itália.'],'Magna = grande: a "Grande Grécia" fora da Grécia.'),
'h-rep2-001':(['Os persas lutaram contra os gregos, não contra Roma nas Púnicas.','Esparta é grega.','A Macedônia não é Cartago.','O Egito não foi o inimigo das Púnicas.'],['Guerras Púnicas: Roma × Cartago; Roma vence.'],'"Púnico" vem do nome que os romanos davam aos cartagineses.'),
'h-rep2-002':(['A monarquia etrusca tinha acabado.','Comerciantes de Cartago eram inimigos.','Escravos não tinham assembleia.','Os tribunos perderam força com a violência.'],['Crise: o Exército vira a instituição forte; soldados fiéis aos generais.'],'O poder dos generais leva aos triunviratos e ao Império.'),
'h-rep2-003':(['As 12 Tábuas não tomaram terras.','Eles não escolheram sair: foram expulsos pela concorrência.','O Tribuno defendia a plebe.','Cartago não invadiu as fazendas.'],['Escravos de graça nos latifúndios → pequeno agricultor quebra.'],'A vitória nas guerras trouxe escravos, e isso prejudicou a plebe.'),
'h-rep2-004':(['Os Graco não propuseram guerra.','Não queriam a monarquia de volta.','Não queriam acabar com o Senado.','Não queriam dar poder aos generais.'],['Irmãos Graco: reforma agrária para a plebe.'],'Os Graco eram tribunos, não generais.'),
'h-rep2-005':(['Reis etruscos são da Monarquia.','Triunvirato não era assembleia.','Leis escritas são as 12 Tábuas.','As Guerras Púnicas não têm esse nome.'],['Triunvirato: três generais dividindo o poder.'],'Tri = três; vir = homem.'),
'h-rep2-006':(['Os Graco não entraram em triunvirato.','Ninguém se mudou para Cartago.','Greve era arma da plebe.','A reforma foi barrada.'],['Patrícios mataram os Graco: a violência entra na política.'],'É o começo do fim da República: conflitos resolvidos pela força.'),
'h-rep2-007':(['Começa pelo fim: o êxodo é consequência.','Escravos vêm das guerras; a guerra é o início.','O êxodo rural é o último passo.','Latifúndios dependem dos escravos das guerras.'],['Guerras → escravos → latifúndios → plebe sem terra → êxodo rural.'],'Pense em causa e consequência: sem guerra, não há escravos baratos.'),
'h-rep2-008':(['A capital não foi para a Grécia.','Não foi libertação de escravos.','Os romanos não foram para Cartago.','Foi a plebe saindo do campo, não os patrícios voltando.'],['Êxodo rural: campo → cidade; plebe pobre e faminta nas cidades.'],'Daí o "pão e circo": acalmar a multidão pobre das cidades.'),
'h-rep2-009':(['Res Publica é a República.','Magna Grécia é o sul da Itália.','Mar Egeu fica entre Grécia e Turquia.','"Mar Romano Interior" não é o nome usado.'],['Mare Nostrum = "Nosso Mar" = Mediterrâneo.'],'Mare Nostrum mostra o tamanho do domínio romano depois de Cartago.'),
'h-rep2-010':(['Rômulo e Remo são da lenda da fundação.','Otávio e Lépido são do 2º.','Esse é o 2º Triunvirato.','Os Graco eram tribunos, não triúnviros.'],['1º: Crasso, Pompeu, Júlio César.','2º: Otávio, Marco Antônio, Lépido.'],'Júlio César está só no 1º; Otávio está só no 2º.'),
'h-rep2-011':(['Caio Graco foi tribuno e morreu antes.','Júlio César foi assassinado em 44 a.C.','Marco Antônio perdeu para Otávio.','Crasso morreu em batalha.'],['Otávio vence os rivais → fim da República → Império (27 a.C.).'],'Quem fecha a República é Otávio, não Júlio César.'),
}
